-- Ref https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/
-- Automatically compact workspaces when a workspace is vacated (dynamic workspaces like in Niri)
local is_compacting = false
local function compact_workspaces()
    if is_compacting then return end
    is_compacting = true

    pcall(function ()
        local wins = hl.get_windows()
        if not wins or #wins == 0 then return end

        local ws_windows = {}
        local ws_ids = {}

        for _, w in ipairs(wins) do
            local ws = w.workspace
            if ws and not ws.special and ws.id and ws.id > 0 then
                if not ws_windows[ws.id] then
                    ws_windows[ws.id] = {}
                    table.insert(ws_ids, ws.id)
                end
                table.insert(ws_windows[ws.id], w)
            end
        end

        if #ws_ids == 0 then return end
        table.sort(ws_ids)

        local mon = hl.get_active_monitor()
        local active_ws_id = (mon and mon.active_workspace and mon.active_workspace.id) and mon.active_workspace.id or 1
        local new_active_ws = active_ws_id

        for target_id, curr_id in ipairs(ws_ids) do
            if curr_id ~= target_id then
                for _, w in ipairs(ws_windows[curr_id]) do
                    hl.dispatch(hl.dsp.window.move({ window = "address:" .. w.address, workspace = target_id }))
                end
                if active_ws_id == curr_id then
                    new_active_ws = target_id
                end
            end
        end

        if new_active_ws ~= active_ws_id then
            hl.dispatch(hl.dsp.focus({ workspace = new_active_ws }))
        end
    end)

    is_compacting = false
end

local function schedule_compact()
    hl.timer(compact_workspaces, { timeout = 150, type = "oneshot" })
end

hl.on("workspace.removed", schedule_compact)
hl.on("window.destroy", schedule_compact)
hl.on("window.close", schedule_compact)
hl.on("window.move_to_workspace", schedule_compact)
