-- Move Windows / Swap Columns (Arrows & Vim keys)
-- Left/Right: swap columns (like Niri move-column-left/right) instead of consume
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.layout("swapcol l"))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.layout("swapcol r"))
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + CTRL + H",     hl.dsp.layout("swapcol l"))
hl.bind(mainMod .. " + CTRL + L",     hl.dsp.layout("swapcol r"))
hl.bind(mainMod .. " + CTRL + J",     hl.dsp.window.move({ workspace = "+1" }))
hl.bind(mainMod .. " + CTRL + K",     hl.dsp.window.move({ workspace = "-1" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + CTRL + [0-9] (Niri style) or mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + CTRL + " .. key,      hl.dsp.window.move({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Special workspace (scratchpad)
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special())

hl.bind(mainMod .. " + SHIFT + S", function ()
    local win = hl.get_active_window()
    if not win then return end
    local ws = win.workspace
    if ws and (ws.special or (ws.id and ws.id < 0) or (ws.name and string.find(ws.name, "special"))) then
        -- Window is inside scratchpad: return it back to current regular workspace
        local mon = hl.get_active_monitor()
        local target_ws = (mon and mon.active_workspace and mon.active_workspace.id and mon.active_workspace.id > 0) and mon.active_workspace.id or 1
        hl.dispatch(hl.dsp.window.move({ workspace = target_ws }))
    else
        -- Window is on regular workspace: send it to special
        hl.dispatch(hl.dsp.window.move({ workspace = "special" }))
    end
end)

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move window across workspaces with mainMod + CTRL + scroll (from Niri)
hl.bind(mainMod .. " + CTRL + mouse_down", hl.dsp.window.move({ workspace = "+1" }))
hl.bind(mainMod .. " + CTRL + mouse_up",   hl.dsp.window.move({ workspace = "-1" }))

-- Scroll horizontally through windows (columns) with mainMod + SHIFT + scroll (from Niri)
hl.bind(mainMod .. " + SHIFT + mouse_down", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + mouse_up",   hl.dsp.focus({ direction = "left" }))

-- Move column left/right with mainMod + CTRL + SHIFT + scroll (from Niri)
